namespace Ordering;

/// <summary>Coordinates product return processing, refunds, and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnProcessor _returnProcessor;
    private readonly RefundService _refundService = new();
    private readonly RestockService _restockService;

    public ReturnsHandler()
    {
        var inventory = new ReturnInventory();
        _returnProcessor = new ReturnProcessor(inventory);
        _restockService = new RestockService(inventory);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returnProcessor.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _returnProcessor.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refundService.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundService.Log(order, amount);

    public int Restock(Order order) =>
        _restockService.Restock(order);
}

internal sealed class ReturnProcessor
{
    private readonly HashSet<string> _processedRefs = new(StringComparer.Ordinal);
    private readonly ReturnInventory _inventory;

    public ReturnProcessor(ReturnInventory inventory)
    {
        _inventory = inventory;
    }

    public string Process(Order order, Customer customer)
    {
        var validationFailure = ValidateRequest(order, customer);
        if (validationFailure is not null)
            return validationFailure;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _inventory.Add(line.Sku, line.Quantity);
        }

        if (_inventory.PendingSkuCount == 0)
            return "no returnable lines";

        _processedRefs.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedRefs.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (IsValidLine(line.Sku, line.Quantity))
                return true;
        }

        return false;
    }

    private string? ValidateRequest(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedRefs.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        return null;
    }

    private static bool IsValidLine(string sku, int quantity) =>
        !string.IsNullOrEmpty(sku) && quantity >= 1 && quantity <= 100;
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
            refund += ComputeLineRefund(line.Quantity);

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _refundLog.Add(FormatEntry(order.Reference, amount));
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    private static decimal ComputeLineRefund(int quantity)
    {
        if (quantity <= 0)
            return 0m;
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;

        return quantity > 1 ? quantity * UnitRefund : UnitRefund;
    }

    private string FormatEntry(string reference, decimal amount)
    {
        if (_refundLog.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}

internal sealed class RestockService
{
    private readonly ReturnInventory _inventory;

    public RestockService(ReturnInventory inventory)
    {
        _inventory = inventory;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (!IsRestockable(line.Sku, line.Quantity))
                continue;

            moved += RestockLine(line.Sku, line.Quantity);
            if (moved > 100000)
                break;
        }

        return moved;
    }

    private int RestockLine(string sku, int quantity)
    {
        if (_inventory.TryTakePending(sku, out var pending))
            return pending;

        _inventory.SetPending(sku, quantity > 50 ? quantity / 2 : quantity);
        return 0;
    }

    private static bool IsRestockable(string sku, int quantity) =>
        !string.IsNullOrEmpty(sku) && quantity > 0 && quantity <= 100;
}

internal sealed class ReturnInventory
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public int PendingSkuCount => _restockBySku.Count;

    public void Add(string sku, int quantity)
    {
        _restockBySku[sku] = _restockBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public bool TryTakePending(string sku, out int pending)
    {
        if (_restockBySku.TryGetValue(sku, out pending) && pending > 0)
        {
            _restockBySku[sku] = 0;
            return true;
        }

        pending = 0;
        return false;
    }

    public void SetPending(string sku, int quantity)
    {
        _restockBySku[sku] = quantity;
    }
}
